467	 * Tell a start coordinate and gap for a placement type.
468	 */
469	static void place_content(lv_flex_align_t place, int32_t max_size, int32_t content_size, int32_t item_cnt,
470	                          int32_t * start_pos, int32_t * gap)
471	{
472	    if(item_cnt <= 1) {
473	        switch(place) {
474	            case LV_FLEX_ALIGN_SPACE_BETWEEN:
475	            case LV_FLEX_ALIGN_SPACE_AROUND:
476	            case LV_FLEX_ALIGN_SPACE_EVENLY:
477	                place = LV_FLEX_ALIGN_CENTER;
478	                break;
479	            default:
480	                break;
481	        }
482	    }
483	
484	    switch(place) {
485	        case LV_FLEX_ALIGN_CENTER:
486	            *gap = 0;
487	            *start_pos += (max_size - content_size) / 2;
488	            break;
489	        case LV_FLEX_ALIGN_END:
490	            *gap = 0;
491	            *start_pos += max_size - content_size;
492	            break;
493	        case LV_FLEX_ALIGN_SPACE_BETWEEN:
494	            *gap = (int32_t)(max_size - content_size) / (int32_t)(item_cnt - 1);
495	            break;
496	        case LV_FLEX_ALIGN_SPACE_AROUND:
497	            *gap += (int32_t)(max_size - content_size) / (int32_t)(item_cnt);
498	            *start_pos += *gap / 2;
499	            break;
500	        case LV_FLEX_ALIGN_SPACE_EVENLY:
501	            *gap = (int32_t)(max_size - content_size) / (int32_t)(item_cnt + 1);
502	            *start_pos += *gap;
503	            break;
504	        default:
505	            *gap = 0;
506	    }
507	}
