509	static lv_obj_t * get_next_item(lv_obj_t * cont, bool rev, int32_t * item_id)
510	{
511	    if(rev) {
512	        (*item_id)--;
513	        if(*item_id >= 0) return cont->spec_attr->children[*item_id];
514	        else return NULL;
515	    }
516	    else {
517	        (*item_id)++;
518	        if((*item_id) < (int32_t)cont->spec_attr->child_cnt) return cont->spec_attr->children[*item_id];
519	        else return NULL;
520	    }
521	}
