42	 ****************************************************************************/
43	static void dm_als_dark_tick(int lux, uint32_t now_ms)
44	{
45	    static uint32_t s_debounce_start = 0;   /* 进入暗光候选的起始时刻 */
46	    static uint32_t s_last_trigger  = 0;    /* 上次弹窗时刻（冷却） */
47	
48	    bool dark_now = (lux >= 0) && (lux < DM_ALS_DARK_LUX);
49	
50	    if (dark_now) {
51	        if (!s_dark_active) {
52	            /* 刚进入暗光：记录候选起点，等 debounce 确认 */
53	            if (s_debounce_start == 0)
54	                s_debounce_start = now_ms;
55	            if (now_ms - s_debounce_start >= DM_ALS_DARK_DEBOUNCE_MS) {
56	                /* 防抖通过：确认暗光 */
57	                s_dark_active = true;
58	                s_debounce_start = 0;
59	                /* 冷却检查：距上次触发 ≥ 冷却期才再次提醒 */
60	                if (s_last_trigger == 0 ||
61	                    now_ms - s_last_trigger >= DM_ALS_DARK_COOLDOWN_MS) {
62	                    s_last_trigger = now_ms;
63	                    if (s_dark_cb)
64	                        s_dark_cb();
65	                }
66	            }
67	        }
68	        /* 已确认暗光：保持，不重复触发（冷却已含） */
69	    }
70	    else {
71	        /* 光线恢复：重置状态机 */
72	        s_dark_active = false;
73	        s_debounce_start = 0;
74	    }
75	}
