    int lux_int = (int)priv->lux;
    int lux_frac = (int)((priv->lux - lux_int) * 100 + 0.5f);
    sninfo("LTR553: ALS : %d.%02d lux (CH0=%d, CH1=%d)\n", lux_int, lux_frac,
          ch0_data, ch1_data);
  }
}

